/* App.css - Modern E-commerce Shopping Cart Styling */

:root {
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --bg-main: #f9fafb;
  --bg-card: #ffffff;
  --text-primary: #111827;
  --text-secondary: #4b5563;
  --text-light: #9ca3af;
  --border-color: #e5e7eb;
  --accent-red: #ef4444;
  --accent-red-hover: #dc2626;
  --accent-green: #10b981;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --radius: 12px;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root {
    --primary: #6366f1;
    --primary-hover: #4f46e5;
    --bg-main: #0f172a;
    --bg-card: #1e293b;
    --text-primary: #f8fafc;
    --text-secondary: #cbd5e1;
    --text-light: #64748b;
    --border-color: #334155;
    --accent-red: #f87171;
    --accent-red-hover: #ef4444;
    --accent-green: #34d399;
  }
}

* {
  box-sizing: border-box;
}

body {
  background-color: var(--bg-main);
  color: var(--text-primary);
  font-family: var(--font-sans);
  margin: 0;
  padding: 0;
}

#root {
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  border-inline: none;
  text-align: left;
}

/* App Layout */
.app-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.app-header {
  background-color: var(--bg-card);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 50;
  box-shadow: var(--shadow-sm);
}

.header-content {
  max-width: 1400px;
  margin: 0 auto;
  padding: 1rem 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo-section {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  text-decoration: none;
  color: inherit;
}

.logo-emoji {
  font-size: 2rem;
}

.app-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin: 0;
  background: linear-gradient(to right, var(--primary), #ec4899);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.header-cart-summary {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background-color: var(--border-color);
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 600;
}

.app-main {
  flex: 1;
  padding: 2rem;
  max-width: 1400px;
  margin: 0 auto;
  width: 100%;
}

.app-footer {
  background-color: var(--bg-card);
  border-top: 1px solid var(--border-color);
  padding: 1.5rem;
  text-align: center;
  color: var(--text-secondary);
  font-size: 0.875rem;
  margin-top: auto;
}

/* Shop Layout Columns */
.shop-layout {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 2rem;
  align-items: start;
}

@media (max-width: 1024px) {
  .shop-layout {
    grid-template-columns: 1fr;
  }
}

/* Filter and Search Bar */
.controls-bar {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 1.25rem;
  margin-bottom: 2rem;
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  align-items: center;
  justify-content: space-between;
  box-shadow: var(--shadow-sm);
}

.search-input-wrapper {
  position: relative;
  flex: 1;
  min-width: 250px;
}

.search-input {
  width: 100%;
  padding: 0.75rem 1rem 0.75rem 2.5rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background-color: var(--bg-main);
  color: var(--text-primary);
  font-size: 0.95rem;
  transition: all 0.2s;
}

.search-input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--border-color);
}

.search-icon {
  position: absolute;
  left: 0.875rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-light);
  font-size: 1.1rem;
}

.category-filters {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.filter-btn {
  background-color: var(--bg-main);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  padding: 0.5rem 1rem;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.filter-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.filter-btn.active {
  background-color: var(--primary);
  border-color: var(--primary);
  color: #ffffff;
}

/* Products Section */
.products-container {
  display: flex;
  flex-direction: column;
}

.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, box-shadow 0.2s;
  box-shadow: var(--shadow-sm);
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.product-image-container {
  background-color: var(--bg-main);
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4.5rem;
  border-bottom: 1px solid var(--border-color);
}

.product-info {
  padding: 1.25rem;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.product-category {
  font-size: 0.75rem;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--text-light);
  letter-spacing: 0.05em;
  margin-bottom: 0.25rem;
}

.product-name {
  font-size: 1.15rem;
  font-weight: 600;
  margin: 0 0 0.5rem 0;
  color: var(--text-primary);
  line-height: 1.3;
}

.product-description {
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
  flex: 1;
  line-height: 1.4;
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
}

.product-price {
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--text-primary);
}

.add-to-cart-btn {
  background-color: var(--primary);
  color: #ffffff;
  border: none;
  padding: 0.625rem 1rem;
  border-radius: 8px;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.add-to-cart-btn:hover {
  background-color: var(--primary-hover);
}

.add-to-cart-btn:active {
  transform: scale(0.97);
}

/* Sidebar Cart Section */
.cart-sidebar {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 1.5rem;
  position: sticky;
  top: 90px;
  box-shadow: var(--shadow-md);
}

.cart-title-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 1rem;
  margin-bottom: 1rem;
}

.cart-title {
  font-size: 1.25rem;
  font-weight: 700;
  margin: 0;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.clear-cart-btn {
  background: none;
  border: none;
  color: var(--text-light);
  font-size: 0.875rem;
  cursor: pointer;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  transition: color 0.2s, background-color 0.2s;
}

.clear-cart-btn:hover {
  color: var(--accent-red);
  background-color: rgba(239, 68, 68, 0.05);
}

.cart-items-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-height: 350px;
  overflow-y: auto;
  padding-right: 0.25rem;
  margin-bottom: 1.5rem;
}

/* Custom Scrollbar for Cart list */
.cart-items-list::-webkit-scrollbar {
  width: 6px;
}
.cart-items-list::-webkit-scrollbar-track {
  background: transparent;
}
.cart-items-list::-webkit-scrollbar-thumb {
  background-color: var(--border-color);
  border-radius: 3px;
}

.cart-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border-color);
}

.cart-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.cart-item-image {
  background-color: var(--bg-main);
  width: 50px;
  height: 50px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.75rem;
  border: 1px solid var(--border-color);
}

.cart-item-details {
  flex: 1;
}

.cart-item-name {
  font-size: 0.9rem;
  font-weight: 600;
  margin: 0 0 0.25rem 0;
  line-height: 1.2;
}

.cart-item-price {
  font-size: 0.875rem;
  color: var(--text-secondary);
  font-weight: 500;
}

.cart-item-controls {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.5rem;
}

.quantity-picker {
  display: flex;
  align-items: center;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  overflow: hidden;
  background-color: var(--bg-main);
}

.qty-btn {
  background: none;
  border: none;
  width: 28px;
  height: 28px;
  cursor: pointer;
  font-weight: bold;
  font-size: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  transition: background-color 0.2s;
}

.qty-btn:hover {
  background-color: var(--border-color);
}

.qty-num {
  font-size: 0.875rem;
  font-weight: 600;
  width: 32px;
  text-align: center;
}

.remove-item-btn {
  background: none;
  border: none;
  color: var(--text-light);
  cursor: pointer;
  font-size: 0.75rem;
  padding: 0.125rem 0.25rem;
  border-radius: 4px;
  transition: color 0.2s;
}

.remove-item-btn:hover {
  color: var(--accent-red);
}

.cart-empty-state {
  text-align: center;
  padding: 3rem 1rem;
  color: var(--text-light);
}

.cart-empty-emoji {
  font-size: 3rem;
  margin-bottom: 1rem;
}

.cart-empty-text {
  font-size: 1rem;
  font-weight: 500;
}

.cart-summary-section {
  border-top: 1px solid var(--border-color);
  padding-top: 1.25rem;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.75rem;
  font-size: 0.95rem;
  color: var(--text-secondary);
}

.summary-row.total {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-top: 0.5rem;
  border-top: 1px dashed var(--border-color);
  padding-top: 0.75rem;
}

.checkout-btn {
  width: 100%;
  background-color: var(--accent-green);
  color: #ffffff;
  border: none;
  padding: 0.875rem;
  border-radius: 8px;
  font-weight: 700;
  font-size: 1rem;
  cursor: pointer;
  margin-top: 1.25rem;
  transition: opacity 0.2s, transform 0.1s;
}

.checkout-btn:hover {
  opacity: 0.9;
}

.checkout-btn:active {
  transform: scale(0.98);
}

/* Loading and Error States */
.loading-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 5rem 2rem;
  gap: 1rem;
}

.spinner {
  border: 4px solid var(--border-color);
  border-top: 4px solid var(--primary);
  border-radius: 50%;
  width: 40px;
  height: 40px;
  animation: spin 1s linear infinite;
}

@keyframes spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

.error-container {
  background-color: rgba(239, 68, 68, 0.05);
  border: 1px solid var(--accent-red);
  padding: 1.5rem;
  border-radius: var(--radius);
  color: var(--accent-red);
  margin-bottom: 2rem;
  text-align: center;
}

.no-results {
  grid-column: 1 / -1;
  text-align: center;
  padding: 4rem 2rem;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  color: var(--text-secondary);
}

import React from 'react';
import {
  createRootRoute,
  createRoute,
  createRouter,
  RouterProvider,
  Outlet,
  useNavigate,
  useSearch,
} from '@tanstack/react-router';
import {
  QueryClient,
  QueryClientProvider,
  useQuery,
} from '@tanstack/react-query';
import { fetchProducts, Product } from './products';
import './App.css';

// Create a client for TanStack Query
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 5, // 5 minutes
      refetchOnWindowFocus: false,
    },
  },
});

// Define CartItem and SearchParams interfaces
interface CartItem {
  productId: number;
  quantity: number;
}

interface ProductSearch {
  cart?: CartItem[];
  category?: string;
  search?: string;
}

// Create a root route with search parameter validation
const rootRoute = createRootRoute({
  validateSearch: (search: Record<string, unknown>): ProductSearch => {
    let cart: CartItem[] = [];
    if (search.cart) {
      try {
        let parsed: any;
        if (typeof search.cart === 'string') {
          parsed = JSON.parse(search.cart);
        } else {
          parsed = search.cart;
        }
        if (Array.isArray(parsed)) {
          cart = parsed
            .map((item: any) => {
              const productId = Number(item?.productId ?? item?.id);
              const quantity = Number(item?.quantity);
              if (!isNaN(productId) && !isNaN(quantity) && quantity > 0) {
                return { productId, quantity };
              }
              return null;
            })
            .filter((item): item is CartItem => item !== null);
        }
      } catch (e) {
        console.error('Failed to parse cart search param', e);
      }
    }
    const category = typeof search.category === 'string' ? search.category : undefined;
    const searchQuery = typeof search.search === 'string' ? search.search : undefined;
    return { cart, category, search: searchQuery };
  },
  component: RootComponent,
});

// Header Component displaying a summary of the cart state
function HeaderCartSummary() {
  const search = useSearch({ from: rootRoute.id });
  const { data: products } = useQuery({
    queryKey: ['products'],
    queryFn: fetchProducts,
  });

  const cart = search.cart || [];
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  const totalPrice = cart.reduce((sum, item) => {
    const product = products?.find((p) => p.id === item.productId);
    return sum + (product ? product.price * item.quantity : 0);
  }, 0);

  return (
    <div className="header-cart-summary">
      <span>🛒 {totalItems} {totalItems === 1 ? 'item' : 'items'}</span>
      <span>•</span>
      <span>${totalPrice.toFixed(2)}</span>
    </div>
  );
}

function RootComponent() {
  return (
    <div className="app-container">
      <header className="app-header">
        <div className="header-content">
          <div className="logo-section">
            <span className="logo-emoji">🛒</span>
            <h1 className="app-title">TanStack Shop</h1>
          </div>
          <HeaderCartSummary />
        </div>
      </header>
      <main className="app-main">
        <Outlet />
      </main>
      <footer className="app-footer">
        <p>© 2026 TanStack Shop. Built with TanStack Query & TanStack Router.</p>
      </footer>
    </div>
  );
}

// Create index route
const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  component: IndexComponent,
});

function IndexComponent() {
  const search = useSearch({ from: '/' });
  const navigate = useNavigate({ from: '/' });

  // Fetch products using TanStack Query
  const { data: products, isLoading, error } = useQuery({
    queryKey: ['products'],
    queryFn: fetchProducts,
  });

  const cart = search.cart || [];
  const activeCategory = search.category || 'All';
  const searchQuery = search.search || '';

  // Get unique categories from products
  const categories = React.useMemo(() => {
    if (!products) return ['All'];
    const unique = new Set(products.map((p) => p.category));
    return ['All', ...Array.from(unique)];
  }, [products]);

  // Filter products based on activeCategory and searchQuery
  const filteredProducts = React.useMemo(() => {
    if (!products) return [];
    return products.filter((product) => {
      const matchesCategory = activeCategory === 'All' || product.category === activeCategory;
      const matchesSearch =
        product.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        product.description.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [products, activeCategory, searchQuery]);

  const handleAddToCart = (productId: number) => {
    const existingItem = cart.find((item) => item.productId === productId);
    let newCart: CartItem[];
    if (existingItem) {
      newCart = cart.map((item) =>
        item.productId === productId ? { ...item, quantity: item.quantity + 1 } : item
      );
    } else {
      newCart = [...cart, { productId, quantity: 1 }];
    }
    navigate({
      search: (prev) => ({ ...prev, cart: newCart }),
    });
  };

  const handleUpdateQuantity = (productId: number, newQuantity: number) => {
    let newCart: CartItem[];
    if (newQuantity <= 0) {
      newCart = cart.filter((item) => item.productId !== productId);
    } else {
      newCart = cart.map((item) =>
        item.productId === productId ? { ...item, quantity: newQuantity } : item
      );
    }
    navigate({
      search: (prev) => ({ ...prev, cart: newCart }),
    });
  };

  const handleRemoveFromCart = (productId: number) => {
    const newCart = cart.filter((item) => item.productId !== productId);
    navigate({
      search: (prev) => ({ ...prev, cart: newCart }),
    });
  };

  const handleClearCart = () => {
    navigate({
      search: (prev) => ({ ...prev, cart: [] }),
    });
  };

  const handleCategorySelect = (category: string) => {
    navigate({
      search: (prev) => ({
        ...prev,
        category: category === 'All' ? undefined : category,
      }),
    });
  };

  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    navigate({
      search: (prev) => ({
        ...prev,
        search: val || undefined,
      }),
    });
  };

  // Calculate cart totals
  const subtotal = React.useMemo(() => {
    if (!products) return 0;
    return cart.reduce((sum, item) => {
      const product = products.find((p) => p.id === item.productId);
      return sum + (product ? product.price * item.quantity : 0);
    }, 0);
  }, [cart, products]);

  const shipping = subtotal > 0 && subtotal < 150 ? 9.99 : 0;
  const total = subtotal + shipping;

  if (isLoading) {
    return (
      <div className="loading-container">
        <div className="spinner"></div>
        <p>Loading the best products for you...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error-container">
        <h2>Error Loading Products</h2>
        <p>{(error as Error).message || 'Something went wrong. Please try again later.'}</p>
      </div>
    );
  }

  return (
    <div className="shop-layout">
      {/* Left Column: Products List with Controls */}
      <div className="products-container">
        {/* Controls Bar: Search & Filters */}
        <div className="controls-bar">
          <div className="search-input-wrapper">
            <span className="search-icon">🔍</span>
            <input
              type="text"
              className="search-input"
              placeholder="Search products..."
              value={searchQuery}
              onChange={handleSearchChange}
            />
          </div>
          <div className="category-filters">
            {categories.map((cat) => (
              <button
                key={cat}
                className={`filter-btn ${activeCategory === cat ? 'active' : ''}`}
                onClick={() => handleCategorySelect(cat)}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Products Grid */}
        {filteredProducts.length === 0 ? (
          <div className="no-results">
            <h3>No products found</h3>
            <p>Try adjusting your search or category filter.</p>
          </div>
        ) : (
          <div className="products-grid">
            {filteredProducts.map((product) => {
              const cartItem = cart.find((item) => item.productId === product.id);
              const quantityInCart = cartItem?.quantity || 0;

              return (
                <div key={product.id} className="product-card">
                  <div className="product-image-container">{product.image}</div>
                  <div className="product-info">
                    <span className="product-category">{product.category}</span>
                    <h3 className="product-name">{product.name}</h3>
                    <p className="product-description">{product.description}</p>
                    <div className="product-footer">
                      <span className="product-price">${product.price.toFixed(2)}</span>
                      <button
                        className="add-to-cart-btn"
                        onClick={() => handleAddToCart(product.id)}
                      >
                        Add to Cart {quantityInCart > 0 && `(${quantityInCart})`}
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Right Column: Shopping Cart Sidebar */}
      <div className="cart-sidebar">
        <div className="cart-title-row">
          <h2 className="cart-title">
            <span>🛒</span> Shopping Cart
          </h2>
          {cart.length > 0 && (
            <button className="clear-cart-btn" onClick={handleClearCart}>
              Clear All
            </button>
          )}
        </div>

        {cart.length === 0 ? (
          <div className="cart-empty-state">
            <div className="cart-empty-emoji">🛍️</div>
            <p className="cart-empty-text">Your cart is empty</p>
            <p style={{ fontSize: '0.875rem', marginTop: '0.5rem' }}>
              Add some products to get started!
            </p>
          </div>
        ) : (
